package com.bank.signaturemanagement.repository; import com.bank.signaturemanagement.entity.SignatureBookEntry; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.List; public interface SignatureBookEntryRepository extends JpaRepository<SignatureBookEntry,Long>{@Query("select e from SignatureBookEntry e join fetch e.employee employee left join fetch employee.designation where e.book.id=:id and (:query='' or lower(employee.employeeNumber) like lower(concat('%',:query,'%')) or lower(employee.fullName) like lower(concat('%',:query,'%'))) order by e.serialNumber,e.signatureType")List<SignatureBookEntry>searchBookEntries(@Param("id")Long id,@Param("query")String query);List<SignatureBookEntry>findByBookIdOrderBySerialNumberAsc(Long id);}
